#!/usr/bin/env bash
# Which label errors keep LaB-RAG from beating retrieval-only? Qwen3.5-27B with the
# image (518 px): attn labels without their false positives (drop-fp) and with their
# misses added (add-fn), next to retrieval-only, attn labels and oracle labels (already
# generated by pilot-image.sh). Diagnostics only: both read the reference labels. Both
# sampling seeds, on the pilot set. Peak 2 GPUs.
set -euo pipefail
cd "$(dirname "$0")/.."

s() { slurm/submit.sh --parsable --kill-on-invalid-dep=yes "$@"; }
B="labrag build-prompts --experiment pilot --section findings"
F=pilot/chexpertplus/findings
CLF=attn-nvfp4-seed1
SET=pilot
P=section-simple-image

p1=$(s -- $B --condition labrag-drop-fp --classifier $CLF --prompt $P)
p2=$(s -- $B --condition labrag-add-fn --classifier $CLF --prompt $P)
NEW="$F/labrag-drop-fp.$CLF.chexbert14.u0/$P $F/labrag-add-fn.$CLF.chexbert14.u0/$P"
OLD="$F/retrieval-only/section-naive-image $F/labrag.$CLF.chexbert14.u0/$P
  $F/labrag-oracle.chexbert14.u0/$P"

gens() { for p in $2; do echo -n "$p/$1/$SET "; done; }
ids=""
runs=""
dep=""
for sampling in qwen3.5-thinking-32k qwen3.5-thinking-32k-seed2; do
  run=qwen3.5-27b-vision.$sampling
  g=$(s -d afterok:$p1:$p2 --gres=gpu:1 -- labrag generate --prompts $NEW --set $SET --model qwen3.5-27b-vision --sampling $sampling)
  e=$(s -d afterok:$g --gres=gpu:1 -- labrag evaluate --generations $(gens $run "$NEW"))
  ids+=" $g $e"
  dep+=":$e"
  runs+=" $(gens $run "$NEW $OLD")"
done
cmp=$(s -d afterok$dep -- labrag compare --generations $runs --out $F/qwen3.5-27b.label-errors/$SET)
echo "prompts $p1 $p2 generate/evaluate$ids compare $cmp"
